  if (count == 0) {
    printf("ERROR: No cuda-capable devices found\n");
    return 2;
  }

  // Initialize cuda before we run the application
  float *dev_X;
  DACE_GPU_CHECK(cudaMalloc((void **)&dev_X, 1));
  DACE_GPU_CHECK(cudaFree(dev_X));

  __state->gpu_context = new dace::cuda::Context(136, 2);

  // Create cuda streams and events
  for (int i = 0; i < 136; ++i) {
    DACE_GPU_CHECK(cudaStreamCreateWithFlags(
        &__state->gpu_context->internal_streams[i], cudaStreamNonBlocking));
    __state->gpu_context->streams[i] =
        __state->gpu_context
            ->internal_streams[i]; // Allow for externals to modify streams
  }
  for (int i = 0; i < 2; ++i) {
    DACE_GPU_CHECK(cudaEventCreateWithFlags(&__state->gpu_context->events[i],
                                            cudaEventDisableTiming));
  }

  return 0;
}

int __dace_exit_cuda(cloudsc_py_state_t *__state) {

  // Synchronize and check for CUDA errors
  int __err = static_cast<int>(__state->gpu_context->lasterror);
  if (__err == 0)
    __err = static_cast<int>(cudaDeviceSynchronize());

  // Destroy cuda streams and events
  for (int i = 0; i < 136; ++i) {
    DACE_GPU_CHECK(
        cudaStreamDestroy(__state->gpu_context->internal_streams[i]));
  }
  for (int i = 0; i < 2; ++i) {
    DACE_GPU_CHECK(cudaEventDestroy(__state->gpu_context->events[i]));
  }

  delete __state->gpu_context;
  return __err;
}

